import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { loadStripe } from '@stripe/stripe-js';
import { Elements, CardElement, useStripe, useElements } from '@stripe/react-stripe-js';
import { bookingAPI, paymentAPI } from '../services/api';
import { FaLock, FaCreditCard } from 'react-icons/fa';

const stripePromise = loadStripe(process.env.REACT_APP_STRIPE_PUBLIC_KEY);

const CheckoutForm = ({ booking }) => {
  const stripe = useStripe();
  const elements = useElements();
  const navigate = useNavigate();
  const [error, setError] = useState(null);
  const [processing, setProcessing] = useState(false);
  const [succeeded, setSucceeded] = useState(false);
  const [clientSecret, setClientSecret] = useState('');

  useEffect(() => {
    if (booking) {
      createPaymentIntent();
    }
  }, [booking]);

  const createPaymentIntent = async () => {
    try {
      const response = await paymentAPI.createPaymentIntent(booking._id);
      setClientSecret(response.data.clientSecret);
    } catch (err) {
      setError('Failed to initialize payment. Please try again.');
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!stripe || !elements) return;

    setProcessing(true);
    setError(null);

    const cardElement = elements.getElement(CardElement);

    const { error: stripeError, paymentIntent } = await stripe.confirmCardPayment(clientSecret, {
      payment_method: {
        card: cardElement,
        billing_details: {
          name: booking.user.name,
          email: booking.user.email,
        },
      },
    });

    if (stripeError) {
      setError(stripeError.message);
      setProcessing(false);
    } else if (paymentIntent.status === 'succeeded') {
      try {
        await paymentAPI.confirmPayment({
          bookingId: booking._id,
          paymentIntentId: paymentIntent.id,
        });
        setSucceeded(true);
        setTimeout(() => navigate('/dashboard'), 2000);
      } catch (err) {
        setError('Payment succeeded but confirmation failed. Please contact support.');
      }
      setProcessing(false);
    }
  };

  const cardElementOptions = {
    style: {
      base: {
        fontSize: '16px',
        color: '#424770',
        '::placeholder': {
          color: '#aab7c4',
        },
      },
      invalid: {
        color: '#9e2146',
      },
    },
  };

  return (
    <form onSubmit={handleSubmit} className="max-w-lg mx-auto">
      <div className="bg-white rounded-xl shadow-lg p-8">
        <div className="flex items-center gap-3 mb-6">
          <div className="bg-primary/10 p-3 rounded-lg">
            <FaCreditCard className="text-primary text-2xl" />
          </div>
          <div>
            <h2 className="text-2xl font-bold">Payment Details</h2>
            <p className="text-sm text-gray-600">Complete your booking securely</p>
          </div>
        </div>

        {/* Booking Summary */}
        <div className="bg-gray-50 rounded-lg p-4 mb-6">
          <h3 className="font-semibold mb-3">Booking Summary</h3>
          <div className="space-y-2 text-sm">
            <div className="flex justify-between">
              <span className="text-gray-600">Property:</span>
              <span className="font-medium">{booking.property?.title}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-gray-600">Check-in:</span>
              <span className="font-medium">{new Date(booking.checkIn).toLocaleDateString()}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-gray-600">Check-out:</span>
              <span className="font-medium">{new Date(booking.checkOut).toLocaleDateString()}</span>
            </div>
            <hr className="my-2" />
            <div className="flex justify-between text-lg font-bold">
              <span>Total:</span>
              <span>${booking.totalPrice.toFixed(2)}</span>
            </div>
          </div>
        </div>

        {/* Card Input */}
        <div className="mb-6">
          <label className="block text-sm font-semibold mb-2">Card Information</label>
          <div className="border border-gray-300 rounded-lg p-4">
            <CardElement options={cardElementOptions} />
          </div>
        </div>

        {/* Error Message */}
        {error && (
          <div className="bg-red-50 border border-red-200 text-red-800 rounded-lg p-4 mb-6">
            {error}
          </div>
        )}

        {/* Success Message */}
        {succeeded && (
          <div className="bg-green-50 border border-green-200 text-green-800 rounded-lg p-4 mb-6">
            ✓ Payment successful! Redirecting to your dashboard...
          </div>
        )}

        {/* Submit Button */}
        <button
          type="submit"
          disabled={!stripe || processing || succeeded}
          className={`w-full py-4 rounded-lg font-semibold text-white flex items-center justify-center gap-2 transition ${
            !stripe || processing || succeeded
              ? 'bg-gray-300 cursor-not-allowed'
              : 'bg-primary hover:bg-primary/90'
          }`}
        >
          <FaLock />
          {processing ? 'Processing...' : `Pay $${booking.totalPrice.toFixed(2)}`}
        </button>

        <p className="text-center text-xs text-gray-500 mt-4">
          <FaLock className="inline mr-1" />
          Your payment information is encrypted and secure
        </p>
      </div>
    </form>
  );
};

const PaymentPage = () => {
  const { bookingId } = useParams();
  const [booking, setBooking] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchBooking();
  }, [bookingId]);

  const fetchBooking = async () => {
    try {
      const response = await bookingAPI.getById(bookingId);
      setBooking(response.data);
    } catch (error) {
      console.error('Error fetching booking:', error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center min-h-screen">
        <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-primary"></div>
      </div>
    );
  }

  if (!booking) {
    return (
      <div className="container mx-auto px-4 py-16 text-center">
        <h1 className="text-3xl font-bold">Booking not found</h1>
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 py-16">
      <Elements stripe={stripePromise}>
        <CheckoutForm booking={booking} />
      </Elements>
    </div>
  );
};

export default PaymentPage;
